package com.bananalab.lite;
import java.util.*;import java.lang.reflect.*;import org.json.*;
/** Scene-effect evaluator independent of rewrite string matching. Local fixtures, not external benchmark. */
final class CapabilityBench{
 static final ThreadLocal<Boolean> testing=new ThreadLocal<>();
 static SceneDraft fixture(Random random){SceneDraft d=new SceneDraft();String[] names={"fito","luna","nico","pipo","lola","tony","tito","nina"};int a=random.nextInt(names.length),b=(a+1+random.nextInt(names.length-1))%names.length;SceneDraft.Actor first=new SceneDraft.Actor(names[a],20),second=new SceneDraft.Actor(names[b],80);String[] kinds={"zorro","banana","pepino","gato"};first.kind=kinds[random.nextInt(4)];second.kind=kinds[random.nextInt(4)];d.cast.add(first);d.cast.add(second);d.focused=first.name;return d;}
 static boolean unchanged(SceneDraft base,CreatorSession.Result result){return result==null||result.commit==null;}
 static String signature(SceneDraft d)throws Exception{JSONObject out=new JSONObject().put("setting",d.setting).put("camera",d.camera);JSONArray cast=new JSONArray(),actions=new JSONArray();for(SceneDraft.Actor a:d.cast)cast.put(new JSONObject().put("name",a.name).put("label",a.label).put("kind",a.kind));for(int i=0;i<d.actions.size();i++)actions.put(new JSONArray().put(d.cast.get(d.actors.get(i)).name).put(d.actions.get(i)).put(d.slot(i)).put(d.target(i)).put(d.recipient(i)));return out.put("cast",cast).put("actions",actions).toString();}
 static CreatorSession.Result apply(String input,SceneDraft base)throws Exception{Boolean old=testing.get();testing.set(Boolean.TRUE);try{return ScenePlanner.apply(input,base.copy());}finally{if(old==null)testing.remove();else testing.set(old);}}
 static boolean result(String mapped,SceneDraft base,String expected)throws Exception{String before=base.json().toString();CreatorSession.Result got=apply(mapped,base);if(!before.equals(base.json().toString()))throw new IllegalStateException("El evaluador modificó la escena base.");if(expected.isEmpty())return unchanged(base,got);if(got==null||got.commit==null||SceneConsistency.problem(got.commit)!=null||!signature(got.commit).equals(expected))return false;for(SceneDraft.Actor actor:base.cast){SceneDraft.Actor next=got.commit.get(actor.name);if(next==null||!next.designId.equals(actor.designId))return false;}return true;}
 static JSONArray fixtures(long seed)throws Exception{Random random=new Random(seed);JSONArray cases=new JSONArray();for(int i=0;i<48;i++){SceneDraft base=fixture(random);String a=base.cast.get(0).name,b=base.cast.get(1).name,input,canonical="";if(i<24){int mode=i%3;input=mode==0?a+" le da un besito a "+b:mode==1?a+" pega un brinco mientras "+b+" hace una reverencia":a+" baila seguido de que "+b+" salta";canonical=mode==0?a+" besa a "+b:mode==1?a+" salta mientras "+b+" saluda":a+" baila despues "+b+" salta";}else{int mode=i%8;input=mode==0?a+" besa a "+b:mode==1?a+" baila despues "+b+" salta":mode==2?a+" salta mientras "+b+" saluda":mode==3?a+" besa a una jirafa":mode==4?a+" no besa a "+b:mode==5?a+" inventa un planeta":mode==6?"que significa besa":a+" dice \"pega un brinco\"";if(mode==7&&i==31)input=a+" dice que le da un besito a "+b;if(mode<3)canonical=input;}String expected="";if(!canonical.isEmpty()){CreatorSession.Result target=apply(canonical,base);if(target==null||target.commit==null)throw new IllegalStateException("Fixture inválido: "+canonical);expected=signature(target.commit);}cases.put(new JSONObject().put("input",input).put("scene",base.json()).put("expected",expected));}return cases;}
 static JSONObject evaluate(Method before,Method after,long seed,JSONArray user)throws Exception{JSONArray cases=fixtures(seed);for(int i=0;i<user.length();i++){JSONObject row=user.getJSONObject(i);SceneDraft base=SceneDraft.read(row.getJSONObject("scene").toString());CreatorSession.Result expected=apply(row.getString("canonical"),base);if(expected==null||expected.commit==null)throw new IllegalArgumentException("Un caso aportado no tiene salida de escena comprobable.");cases.put(new JSONObject().put("input",row.getString("input")).put("scene",base.json()).put("expected",signature(expected.commit)));}int old=0,next=0,regressions=0;for(int i=0;i<cases.length();i++){JSONObject row=cases.getJSONObject(i);String input=row.getString("input");SceneDraft base=SceneDraft.read(row.getJSONObject("scene").toString());boolean a=result((String)before.invoke(null,input),base,row.getString("expected")),b=result((String)after.invoke(null,input),base,row.getString("expected"));if(input.contains(" dice ")){a&=((String)before.invoke(null,input)).equals(input);b&=((String)after.invoke(null,input)).equals(input);}if(a)old++;if(b)next++;if(a&&!b)regressions++;}return new JSONObject().put("before",old).put("after",next).put("total",cases.length()).put("regressions",regressions).put("seed",seed).put("source","local_generated_scene_fixtures");}
 static JSONObject validateUser(JSONArray rows)throws Exception{if(rows.length()>8||rows.toString().length()>180000)throw new IllegalArgumentException("Hasta8 correcciones de escena.");Set<String> seen=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);RuntimeProgram.keys(row,"input","canonical","scene","source");new UnderstandingSpec(0,new JSONArray().put(new JSONObject().put("input",row.getString("input")).put("canonical",row.getString("canonical"))));if(!seen.add(row.getString("input"))||!row.getString("source").equals("user_specification"))throw new IllegalArgumentException("Caso inválido.");SceneDraft scene=SceneDraft.read(row.getJSONObject("scene").toString());CreatorSession.Result result=apply(row.getString("canonical"),scene);if(result==null||result.commit==null||SceneConsistency.problem(result.commit)!=null)throw new IllegalArgumentException("No puedo comprobar el significado de esa corrección.");}return new JSONObject().put("validated",rows.length());}
}
